package com.tekwatt.admin.dto;import com.tekwatt.admin.entity.AdminApiKey;import java.time.Instant;import java.util.UUID;public record ApiKeyResponse(UUID id,UUID tenantId,String keyId,String secret,String name,String roleName,String scopes,String status,Instant createdAt){public static ApiKeyResponse from(AdminApiKey k,String secret){return new ApiKeyResponse(k.getId(),k.getTenantId(),k.getKeyId(),secret,k.getName(),k.getRoleName(),k.getScopes(),k.getStatus(),k.getCreatedAt());}}
